import {fetchFr24Public} from "./fr24-public-html.js";
import {guardedFetch} from "./fs-guard.js";
import {noteActualAircraft} from "./aircraft-change.js";
import {regHeldByNearbyFlight} from "./reg-nearby.js";

const clean=v=>String(v??"").trim();
const upper=v=>clean(v).toUpperCase();
const hhmm=v=>{const m=clean(v).match(/(\d{1,2}):(\d{2})/);return m?`${String(Number(m[1])).padStart(2,"0")}:${m[2]}`:""};
const parisDate=()=>new Intl.DateTimeFormat("fr-CA",{timeZone:"Europe/Paris",year:"numeric",month:"2-digit",day:"2-digit"}).format(new Date());
const manual=x=>/MANUAL/.test(upper(x));
const FR24_EXACT_OCCURRENCES={"TK1830|2026-10-03":"41f2d733"};
function flight(row,x){const airline=upper(x.airline||row.airline),designator=upper(x.flight||row.flight_number),number=designator.startsWith(airline)?designator.slice(airline.length):String(row.flight_number||"").replace(/^[A-Z0-9]{2,3}(?=\d)/,"");const exact=FR24_EXACT_OCCURRENCES[`${designator}|${row.flight_date}`]||clean(x.fr24OccurrenceId||x.fr24_occurrence_id);return {date:row.flight_date,designator,airline,number,origin:upper(x.origin||"CDG"),destination:upper(x.destination||x.dest||""),raw:{...x,fr24OccurrenceId:exact}}}
function textOnly(html){return String(html||"").replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi," ").replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi," ").replace(/<[^>]+>/g," ").replace(/&nbsp;/gi," ").replace(/&amp;/gi,"&").replace(/&#39;/g,"'").replace(/&quot;/gi,'"').replace(/\s+/g," ").trim()}
function gateFromText(text,f){const u=upper(text),keys=[upper(f.designator),`${upper(f.airline)} ${upper(f.number)}`];let i=-1;for(const k of keys){i=u.indexOf(k);if(i>=0)break}if(i<0)return "";const w=text.slice(Math.max(0,i-900),Math.min(text.length,i+1800));if(f.destination&&!upper(w).includes(f.destination))return "";for(const p of [/(?:PORTE|GATE)\s*[:\-]?\s*([A-Z]?\d{1,3}[A-Z]?)/i,/\b([A-Z]\d{1,3}[A-Z]?)\b\s*(?:PORTE|GATE)/i,/"gate"\s*:\s*"([A-Z]?\d{1,3}[A-Z]?)"/i]){const m=w.match(p);if(m)return upper(m[1])}return ""}
function genericFields(text,f){const u=upper(text),keys=[upper(f.designator),`${upper(f.airline)} ${upper(f.number)}`];let i=-1;for(const k of keys){i=u.indexOf(k);if(i>=0)break}if(i<0)return {gate:"",type:"",reg:""};const w=text.slice(Math.max(0,i-1200),Math.min(text.length,i+2600));if(f.destination&&!upper(w).includes(f.destination))return {gate:"",type:"",reg:""};const gate=gateFromText(w,f)||((w.match(/"gate"\s*:\s*"([A-Z]?\d{1,3}[A-Z]?)"/i)||[])[1]||"");const type=((w.match(/\b(A20N|A21N|A319|A320|A321|A332|A333|A339|A343|A350|A359|A380|B737|B738|B739|B748|B752|B753|B763|B764|B772|B773|B77W|B788|B789|32Q|77W|788|789|359|333|332|320|321)\b/i)||[])[1]||"");const reg=((w.match(/\b(F-[A-Z]{4}|TC-[A-Z]{3}|TS-[A-Z]{3}|SU-[A-Z]{3}|CC-[A-Z]{3}|9V-[A-Z]{3}|9M-[A-Z]{3}|EI-[A-Z]{3}|SP-[A-Z]{3}|YU-[A-Z]{3}|LZ-[A-Z]{3}|9XR-[A-Z]{2,3}|N\d{1,5}[A-Z]{0,2}|[A-Z]{1,2}-[A-Z]{3,5})\b/i)||[])[1]||"");return {gate:upper(gate),type:upper(type),reg:upper(reg)}}
async function fetchText(url){const c=new AbortController(),t=setTimeout(()=>c.abort(),4500);try{const r=await guardedFetch(url,{redirect:"follow",signal:c.signal,headers:{accept:"text/html,application/xhtml+xml","accept-language":"fr-FR,fr;q=0.9,en;q=0.8","user-agent":"Mozilla/5.0 (compatible; AlyziaOpsV2-Ground/1.3)"}});return r.ok?textOnly(await r.text()):""}catch{return ""}finally{clearTimeout(t)}}
async function parisBoard(){return fetchText("https://www.parisaeroport.fr/en/passengers/flights/all-flights-departures")}
const GATE_FALLBACKS=[
 ["FLIGHTSTATS",f=>`https://www.flightstats.com/v2/flight-tracker/${encodeURIComponent(f.airline)}/${encodeURIComponent(f.number)}?year=${f.date.slice(0,4)}&month=${Number(f.date.slice(5,7))}&date=${Number(f.date.slice(8,10))}`],
 ["FLIGHTAWARE",f=>`https://www.flightaware.com/live/flight/${encodeURIComponent(f.designator)}`],
 ["PLANEFINDER",f=>`https://planefinder.net/data/flight/${encodeURIComponent(f.designator)}`],
 ["SKYSCANNER",f=>`https://www.skyscanner.net/flight-tracker/${encodeURIComponent(f.designator.toLowerCase())}`],
 ["FLIGHTVIEW",f=>`https://www.flightview.com/flight-tracker/${encodeURIComponent(f.airline)}/${encodeURIComponent(f.number)}`],
 ["WEGO",f=>`https://www.wego.com/schedules/${encodeURIComponent(f.designator)}?date=${encodeURIComponent(f.date)}`],
 ["IXIGO",f=>`https://www.ixigo.com/flight-status/${encodeURIComponent(f.airline.toLowerCase())}-${encodeURIComponent(f.number)}?date=${encodeURIComponent(f.date)}`],
 ["KAYAK",f=>`https://www.kayak.com/tracker/${encodeURIComponent(f.designator)}`],
 ["FLIGHTERA",f=>`https://www.flightera.net/en/flight/${encodeURIComponent(f.designator)}`],
 ["FLIGHTY",()=>"https://flighty.com/airports/paris-charles-de-gaulle-cdg/departures"],
 ["FLIGHTRADARS24_FR",()=>"https://flightradars24.fr/aeroport-charles-de-gaulle/depart/"],
 ["SIMPLEFLYING",()=>"https://simpleflying.com/flight-tracker/"]
];
export const GATE_PUBLIC_SOURCE_ORDER=["Paris Aéroport","FR24","FlightStats","FlightAware","PlaneFinder","Skyscanner","FlightView","Wego","Ixigo","Kayak","Flightera","Flighty","Flightradars24.fr","SimpleFlying"];
async function gateWithFallbacks(f,board,fr){const attempts=[];let gate=gateFromText(board,f);attempts.push({source:"PARIS_AEROPORT",status:gate?"OK":board?"NO_GATE":"NO_DATA"});if(gate)return {gate,source:"PARIS_AEROPORT",attempts};const fc=fr?.candidates||{},fs=fc.semantic||{};gate=upper(fs.gateOrigin||fc.gates?.[0]);attempts.push({source:"FR24",status:gate?"OK":clean(fr?.status)||"NO_GATE"});if(gate)return {gate,source:"FR24",attempts};for(const [source,build] of GATE_FALLBACKS){if(source==="FLIGHTAWARE")continue;   // FlightAware : ATD uniquement, jamais la porte
const text=await fetchText(build(f));const fields=genericFields(text,f);attempts.push({source,status:fields.gate?"OK":text?"NO_GATE":"NO_DATA"});if(fields.gate)return {gate:fields.gate,source,attempts}}return {gate:"",source:"",attempts}}
async function readCurrent(env,id){const r=await env.OPS_DB.prepare(`SELECT data_json FROM flights WHERE identity=? LIMIT 1`).bind(id).first();if(!r)return null;try{return JSON.parse(r.data_json||"{}")}catch{return {}}}
async function saveMeta(env,data){try{await env.OPS_DB.prepare(`CREATE TABLE IF NOT EXISTS ops_meta(k TEXT PRIMARY KEY,v TEXT)`).run();await env.OPS_DB.prepare(`INSERT INTO ops_meta(k,v) VALUES('v2_ground_public_last',?) ON CONFLICT(k) DO UPDATE SET v=excluded.v`).bind(JSON.stringify(data)).run()}catch{}}
async function mapLimit(items,limit,fn){const out=new Array(items.length);let n=0;await Promise.all(Array.from({length:Math.min(limit,items.length)},async()=>{for(;;){const i=n++;if(i>=items.length)return;out[i]=await fn(items[i])}}));return out}

async function apply(env,row,board){let initial={};try{initial=JSON.parse(row.data_json||"{}")}catch{};const f=flight(row,initial),at=new Date().toISOString();let type="",reg="",frStatus="",fr=null;
  try{fr=await fetchFr24Public(f);frStatus=fr?.status||"";const c=fr?.candidates||{},s=c.semantic||{};type=upper(s.type||c.aircraft?.[0]);reg=upper(s.reg)}catch{frStatus="FETCH_ERROR"}
  const gateHit=await gateWithFallbacks(f,board,fr);
  const x=await readCurrent(env,row.identity);if(!x)return {flight:f.designator,status:"FLIGHT_DISAPPEARED"};let changed=false;
  if(gateHit.gate&&!manual(x.gateSource)&&!/FR24BOARD/.test(upper(x.gateSource))&&upper(x.gate)!==gateHit.gate){const from=clean(x.gate);x.gate=gateHit.gate;x.gateSource=gateHit.source;x.gateUpdatedAt=at;(x.flightInfoLog??=[]).unshift({at,source:gateHit.source,field:"gate",from,to:gateHit.gate});changed=true}
  if(type&&!manual(x.aircraftActualSource)){if(noteActualAircraft(x,type,"FR24",at))changed=true}
  // Le tableau FR24 fait foi ; une immatriculation déjà portée par un autre départ CDG à moins de 2 h est une mauvaise lecture de la page du vol (D-AIHV sur une dizaine de vols).
  if(reg&&upper(x.reg||x.registration)!==reg&&((/FR24BOARD/.test(upper(x.regSource||x.registrationSource))&&clean(x.reg||x.registration))||await regHeldByNearbyFlight(env,row.identity,f.date,reg,x.std||f.std)))reg="";
  if(reg&&!manual(x.regSource||x.registrationSource)&&upper(x.reg||x.registration)!==reg){const from=clean(x.reg||x.registration);x.reg=reg;x.registration=reg;x.regSource="FR24";x.registrationSource="FR24";x.regUpdatedAt=at;(x.flightInfoLog??=[]).unshift({at,source:"FR24",field:"reg",from,to:reg});changed=true}
  if(changed){x.groundBackfill={checkedAt:at,gateSource:gateHit.source||null,gateAttempts:gateHit.attempts,fr24Status:frStatus,fr24OccurrenceId:clean(f.raw?.fr24OccurrenceId)||null,gate:gateHit.gate||null,type:type||null,reg:reg||null};if(Array.isArray(x.flightInfoLog))x.flightInfoLog=x.flightInfoLog.slice(0,200);await env.OPS_DB.prepare(`UPDATE flights SET data_json=?,updated_at=CURRENT_TIMESTAMP WHERE identity=?`).bind(JSON.stringify(x),row.identity).run()}
  return {flight:f.designator,status:changed?"UPDATED":"UNCHANGED",gate:gateHit.gate||"",gateSource:gateHit.source||"",type:type||"",reg:reg||"",fr24OccurrenceId:clean(f.raw?.fr24OccurrenceId)||"",gateAttempts:gateHit.attempts}}

export async function runGroundPublicFlow(env,{concurrency=6}={}){if(!env?.OPS_DB)return {ok:false,error:"NO_DB"};const date=parisDate(),startedAt=new Date().toISOString(),board=await parisBoard();const {results=[]}=await env.OPS_DB.prepare(`SELECT identity,flight_date,flight_number,airline,data_json FROM flights WHERE flight_date=? AND airline<>'SYS' ORDER BY std,flight_number`).bind(date).all();const out=await mapLimit(results,Math.max(1,Math.min(8,Number(concurrency)||6)),r=>apply(env,r,board));const summary={ok:true,mode:"GROUND_PUBLIC_15MIN",date,startedAt,finishedAt:new Date().toISOString(),checked:results.length,updated:out.filter(x=>x.status==="UPDATED").length,parisAeroportBoard:Boolean(board),gatePrimary:"PARIS_AEROPORT",gateSources:GATE_PUBLIC_SOURCE_ORDER,typePrimary:"FR24",registrationPrimary:"FR24",statusCounts:{}};for(const r of out)summary.statusCounts[r.status]=(summary.statusCounts[r.status]||0)+1;await saveMeta(env,summary);return {...summary,results:out}}
export async function groundPublicStatus(env){let last=null;try{const r=await env.OPS_DB.prepare(`SELECT v FROM ops_meta WHERE k='v2_ground_public_last'`).first();if(r?.v)last=JSON.parse(r.v)}catch{}return {ok:true,cadenceMinutes:15,gatePrimary:"PARIS_AEROPORT",gateSources:GATE_PUBLIC_SOURCE_ORDER,typePrimary:"FR24",registrationPrimary:"FR24",lastRun:last}}
