function localFlight(x){try{return (typeof FLIGHTS!=='undefined'?FLIGHTS:[]).find(f=>String(f.flight||'').toUpperCase()===String(x.flight||'').toUpperCase()&&String(f.date||adminDate)===String(x.date||adminDate))||null}catch{return null}}
function terminalOf(x){const f=localFlight(x);let t=String(f?.terminal||f?.departureTerminal||x.terminal||'').toUpperCase();if(/^1$/.test(t))t='T1';if(/^2/.test(t))t='T2';if(/^3$/.test(t))t='T3';if(!/^T[123]$/.test(t)){try{const a=String(f?.airline||'').toUpperCase();if(typeof AIRLINE_TERMINAL!=='undefined'&&AIRLINE_TERMINAL[a])t=AIRLINE_TERMINAL[a]}catch{}}return /^T[123]$/.test(t)?t:'—'}
