function openQuota(provider){const q=(cache?.quotas||[]).find(x=>x.provider===provider);if(!q)return;const used=q.period==='day'?q.today:q.month;const html='<div class="adn-api-modal"><div class="adn-api-kpis"><div class="adn-api-kpi"><small>AUJOURD’HUI</small><b>'+esc(q.today||0)+'</b></div><div class="adn-api-kpi"><small>CE MOIS</small><b>'+esc(q.month||0)+(q.limit?' / '+esc(q.limit):'')+'</b></div><div class="adn-api-kpi"><small>RESTANT SÉCURISÉ</small><b>'+esc(q.remaining==null?'—':q.remaining)+'</b></div><div class="adn-api-kpi"><small>RÉSERVE</small><b>'+esc(q.reserve||0)+'</b></div></div><div class="adn-api-meta">PÉRIODE DE QUOTA : '+esc(q.period==='day'?'JOUR':'MOIS')+'<br>UTILISATION PRISE EN COMPTE : '+esc(used||0)+'<br>DERNIER HTTP : '+esc(q.lastStatus??'—')+'<br>DERNIÈRE REQUÊTE : '+esc(q.lastAt?new Date(q.lastAt).toLocaleString('fr-FR'):'—')+'</div></div>';if(typeof showModal==='function')showModal(provider,'UTILISATION DU QUOTA API',html)}
function logMarkup(rows){const done=[...rows].filter(x=>x.checkedAt).sort((a,b)=>String(b.checkedAt).localeCompare(String(a.checkedAt))).slice(0,12);const todo=rows.filter(x=>x.state!=='OK').slice(0,12);return '<div class="adn-log"><div class="adn-log-col"><h4>DERNIERS TRAITEMENTS</h4>'+(done.length?done.map(x=>'<div class="adn-log-line"><b>'+esc(hh(x.checkedAt))+'</b><span>'+esc(x.flight)+'</span><span>'+esc(x.state)+'</span></div>').join(''):'<div class="adn-empty">AUCUN TRAITEMENT HORODATÉ</div>')+'</div><div class="adn-log-col"><h4>À VENIR / PROCHAIN TRAITEMENT</h4>'+(todo.length?todo.map(x=>'<div class="adn-log-line"><b>'+esc(x.std||'—')+'</b><span>'+esc(x.flight)+'</span><span>'+esc(nextAction(x))+'</span></div>').join(''):'<div class="adn-empty">AUCUNE ACTION EN ATTENTE</div>')+'</div></div>'}
const MAJ_LABEL={gate:'GATE',reg:'REG',aircraft:'A/C',aircraftActual:'A/C',etd:'ETD',atd:'ATD',eta:'ETA',ata:'ATA',takeoff:'TO',landing:'LDG',status:'STATUT'};
